  "path": "src/cli-verbs.ts",
  "suggestion_code": "  let verdict: string;\n  if (!s.daemonOk) verdict = \"DOWN\";\n  else if (fresh) verdict = \"RUNNING\";\n  else verdict = \"STALE\";"
